def run(code):
    """รันโค้ดตัวอย่างแล้วคืนค่าที่ print (ใช้ตรวจเฉลย)"""
    import contextlib
    import io
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        exec(code, {})
    return buf.getvalue().strip()


